//! The reduced Helmholtz energy of the chain term of the PC-SAFT model
//! against the exact-source library.
//! Generated by tools/rust_port/validate_pcsaft_chain.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::pc_saft::pcsaft_chain_energy;

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn the_chain_term_matches_the_source() {
    let mut rows = include_str!("fixtures/pcsaft_chain.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(header, "case;F;F_t;F_v;F_n;F_tt;F_tv;F_tn;F_vv;F_vn;F_nn");
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 4, "case {row}");
        let components: Vec<&str> = case[0].split(',').collect();
        let count = components.len();
        // The number of values depends on the number of components: the
        // reduced Helmholtz energy, its temperature and volume derivatives,
        // the derivatives with respect to the mole numbers and their second
        // derivatives.
        assert_eq!(fields.len(), 7 + 3 * count + count * count, "row {row}");
        let temperature: f64 = case[1].parse().expect("the temperature");
        let volume: f64 = case[2].parse().expect("the volume");
        let moles: Vec<f64> = case[3]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let model = thermopack_rs::PcSaft::new(&components).expect("the model of the case");
        let energy = pcsaft_chain_energy(&model, temperature, volume, &moles)
            .expect("the energy of the case");
        let mut native = vec![energy.value, energy.d_t, energy.d_v];
        native.extend(energy.d_n.iter().copied());
        native.push(energy.d_tt);
        native.push(energy.d_tv);
        native.extend(energy.d_tn.iter().copied());
        native.push(energy.d_vv);
        native.extend(energy.d_vn.iter().copied());
        for row in &energy.d_nn {
            native.extend(row.iter().copied());
        }
        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn a_component_without_segments_has_no_chain_term() {
    // The chain term of the original sums over the components with more than
    // one segment only.
    let model = thermopack_rs::PcSaft::new(&["CO2"]).expect("the model");
    let segments = model.components()[0].m;
    if segments <= 1.0 {
        let energy = pcsaft_chain_energy(&model, 300.0, 1.0e-3, &[0.1]).expect("the energy");
        assert_eq!(energy.value, 0.0);
        assert_eq!(energy.d_t, 0.0);
        assert_eq!(energy.d_v, 0.0);
    }
}

#[test]
fn a_wrong_number_of_moles_is_rejected() {
    let model = thermopack_rs::PcSaft::new(&["CO2", "C1"]).expect("the model");
    assert!(pcsaft_chain_energy(&model, 300.0, 1.0e-3, &[0.1]).is_err());
    assert!(pcsaft_chain_energy(&model, 300.0, 1.0e-3, &[0.1, 0.1, 0.1]).is_err());
    assert!(pcsaft_chain_energy(&model, 300.0, -1.0e-3, &[0.1, 0.1]).is_err());
    assert!(pcsaft_chain_energy(&model, 300.0, 1.0e-3, &[-0.1, 0.1]).is_err());
}
